const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.RGB, 100);//RGB 100dankai
p5obj.background(0);//black haikei
p5obj.stroke(10, 55, 60);//green?
p5obj.strokeWeight(2);
p5obj.noFill();//sikakuno sendakenisuru
var a=15;
var c=4*a;
for (var y=-1; y<500; y++)
{
  for (var x=-2; x<500; x=x+2)
  {
    p5obj.quad(c*x+0, c*y+40, c*x+20, c*y+10, c*x+60, c*y+10, c*x+40, c*y+40);//sikaku_a1
    p5obj.quad(c*x+0, c*y+40, c*x+20, c*y+70, c*x+60, c*y+70, c*x+40, c*y+40);//sikaku_b1
    p5obj.quad(c*x+60, c*y+10, c*x+100, c*y+10, c*x+120, c*y+-20, c*x+80, c*y+-20);//sikaku_a2
    p5obj.quad(c*x+60, c*y+70, c*x+80, c*y+100, c*x+120, c*y+100, c*x+100, c*y+70);//sikaku_b2
    p5obj.line(y*60, 0, y*60, 500);//tate
    p5obj.line(c*x+0, c*y+40, c*x+60, c*y+10);//naname_ue
    p5obj.line(c*x+0, c*y+40, c*x+60, c*y+70);//naname_sita
    p5obj.line(c*x+60, c*y+10, c*x+120, c*y+-20);//naname_ue2
    p5obj.line(c*x+60, c*y+70, c*x+120, c*y+100);//naname_sita2
  }
}

  };
};

export default sketch;
