const sketch = (p5obj:any) => {
/**************************************************************
立方体に明るい面と暗い面を用意し、どの面を正面に向けるかでデジタル時計のような
時刻の表示ができるようにしました。立方体は四角形を縦に長い楕円に沿うように動かし、
それぞれの頂点を辺で結ぶことで再現しています。
 **************************************************************/
/**
  デバッグ機能
    'S'キー：png出力
    'H'キー：時が変わったときのアニメーション再生
    'M'キー：分が変わったときのアニメーション再生
*/
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A09_Koshiya.png";

// === アニメーション用変数/定数 ===
//横七列で7セグメント表示の各位置、縦六列で各位の情報を持つ二次元配列を宣言
let iRStoH: number[][] = Array.from({ length: 6 }, () => Array(7).fill(0));
//大きさ調整用変数
//どれだけ横から見るか
let iRL: number = 5;
//どれだけ縦を伸ばすか
let iYL: number = 10;
//どれだけ横に伸ばすか
let iXL: number = 12.5;

//色調整用
//暗い面の色
let iDC: number = 40;
//明るい面の色
let iLCR: number = 255;
let iLCG: number = 255;
let iLCB: number = 255;
//中くらいの面の色
let iMC: number = 60;

//コロン回転用変数
let iColonR: number = 0;

//7セグメント表示でどのセグメントがどんなタイミングで明るくなるかを表す二次元配列。左から0~9
let iPos: number[][] = [
  [ 1, 0, 1, 1, 0, 1, 1, 1, 1, 1 ],//上部
  [ 1, 1, 1, 1, 1, 0, 0, 1, 1, 1 ],//右上
  [ 1, 1, 0, 1, 1, 1, 1, 1, 1, 1 ],//右下
  [ 1, 0, 1, 1, 0, 1, 1, 0, 1, 1 ],//下部
  [ 1, 0, 1, 0, 0, 0, 1, 0, 1, 0 ],//左下
  [ 1, 0, 0, 0, 1, 1, 1, 0, 1, 1 ],//左上
  [ 0, 0, 1, 1, 1, 1, 1, 0, 1, 1 ]
];//中心

// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;
 
p5obj.setup = (): void =>
{
  p5obj.createCanvas( 800, 205 );
  p5obj.frameRate( 30 );  // フレームレートの指定
 
  // === Time Init ===
  p5obj.initTime();
  //角度の情報を一旦全て45にし、見かけ上の0度にする
  for( let i=0; i < iRStoH.length; i++ )
  {
    for( let j=0; j < iRStoH[i].length; j++ )
    {
      iRStoH[i][j] = 45;
    }
  }
  //一度動かしておかないと表示されないんです
  secondPrev = -1;
  minutePrev = -1;
  hourPrev = -1;
  //つなぎ目を滑らかに
  p5obj.strokeJoin(p5obj.BEVEL);
}

p5obj.draw = (): void =>
{  
  // === Time Update ===
  p5obj.updateTimePre();
 
  //hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化
 
  // === 画面のクリア ===
 
  // 画面をクリア
  p5obj.fill( 0 );
  p5obj.noStroke();
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );

  // 既定の描画カラーに戻す．
  p5obj.fill( 255 );
  p5obj.stroke( 255 );
 
  // === アニメーションを記述 ===
  //枠線削除
  p5obj.noStroke();
  
  //各位の
  //秒数一の位を並べる
  p5obj.locateBox( 750, 0 );
  //秒数十の位を並べる
  p5obj.locateBox( 625, 1 );
  //分数一の位を並べる
  p5obj.locateBox( 477.5, 2 );
  //分数十の位を並べる
  p5obj.locateBox( 352.5, 3 );
  //時間一の位を並べる
  p5obj.locateBox( 205, 4 );
  //時間十の位を並べる
  p5obj.locateBox( 80, 5 );
  //コロン書く
  p5obj.drawColon( 256.5, 75 );
  p5obj.drawColon( 256.5, 127.5 );
  p5obj.drawColon( 530, 75 );
  p5obj.drawColon( 530, 127.5 );
 
  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始

    // アニメーション初期化
   
   
  }
  if ( isSecondAnim == 1 )  // アニメーション中
  {
    //秒数一の位の各セグメントの情報をiPosから仕入れ、iRStoHに入れる
    for( let a=0; a < iRStoH[0].length; a++ )
    {
      iRStoH[0][a] = p5obj.rotateBox( a, secondCurrent % 10,iRStoH[0][a] );
    }
    //秒数十の位
    for( let b = 0; b < iRStoH[0].length; b++ )
    {
      iRStoH[1][b] = p5obj.rotateBox( b, ( secondCurrent - ( secondCurrent % 10 ) ) / 10,iRStoH[1][b] );
    }
    //isSecondAnim = 0;

  }
 
 
  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始
   
    // アニメーション初期化
   
   
  }
  if( isMinuteAnim == 1 )  // アニメーション中
  {
    
    // アニメーション中の処理を記述
    //分数一の位
    for( let c=0; c < iRStoH[0].length; c++ )
    {
      iRStoH[2][c] = p5obj.rotateBox( c, minuteCurrent % 10,iRStoH[2][c] );
    }
    //分数十の位
    for( let d = 0; d < iRStoH[0].length; d++ )
    {
      iRStoH[3][d] = p5obj.rotateBox( d, ( minuteCurrent - ( minuteCurrent % 10 ) ) / 10,iRStoH[3][d] );
    }
   
   
   
    //isMinuteAnim = 0;  // アニメーション終了
  }
 
 
  // 時が変化した時のアニメーション
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始
   
    // アニメーション初期化
   
   
  }
  if( isHourAnim == 1 )
  {
    // アニメーション中の処理を記述
    //時間一の位
    for( let e=0; e < iRStoH[0].length; e++ )
    {
      iRStoH[4][e] = p5obj.rotateBox( e, hourCurrent % 10,iRStoH[4][e] );
    }
    //時間十の位
    for( let f = 0; f < iRStoH[0].length; f++ )
    {
      iRStoH[5][f] = p5obj.rotateBox( f, ( hourCurrent - ( hourCurrent % 10 ) ) / 10,iRStoH[5][f] );
    }
    //isHourAnim = 0;  // アニメーション終了
  }
 
  // 時間をデバッグ表示（ 提出前に非表示にすること．）
  /*
  p5obj.fill( 0 );
  p5obj.textSize(20);  // フォントサイズを10に変更
  p5obj.text( hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 5, 10);
  p5obj.text( "deltaTimePerSec: " + deltaTimePerSec, 5, 20);
  p5obj.text( "deltaTime: " + deltaTime, 5, 30);
  */
 
  // === Time Update ===
  p5obj.updateTimePost();
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}

p5obj.updateTimePre = (): void =>
{
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

//描画用関数
p5obj.drawBox = (iR: number): void =>
{
  //白い面を作成
  p5obj.fill( iLCR, iLCG, iLCB );
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 180 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 180 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 270 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 270 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 180 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iR + 180 ) ) );
  p5obj.endShape( p5obj.CLOSE );
 
  //黒い面を作成
  p5obj.fill( iDC );
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 270 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR ) ) , iYL * p5obj.sin( p5obj.radians( iR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 270 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iR + 270 ) ) );
  p5obj.endShape( p5obj.CLOSE );
  
  //横の面を作成
  p5obj.fill( iMC );
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 180 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 180 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 270 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR ) ) , iYL * p5obj.sin( p5obj.radians( iR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iR + 90 ) ) , iYL * p5obj.sin( p5obj.radians( iR + 90 ) ) );
  p5obj.endShape( p5obj.CLOSE );
}
//各位の各セグメントの情報をiPosから仕入れ、iRStoHに入れ、回転の角度を返す関数
p5obj.rotateBox = (iPlace: number, iNow: number, iRR: number): number =>
{
  if( iPos[iPlace][iNow] == 1 )
    {
      //90度より傾きすぎないようにする分岐
      if( iRR < 135 )
      {
        iRR += 4;
      }
    }
    else
    {
      //0度未満に傾きすぎないようにする分岐
      if( iRR > 45 )
      {
        iRR -= 4;
      }
    }
    return iRR;
}


p5obj.locateBox = (iCenter: number, iUnit: number): void =>
{
  p5obj.push();
  //各位の位置、明暗、位の情報をもとに箱を並べていく
  //秒数一の位上部
  p5obj.translate( iCenter, 25 );
  p5obj.drawBox( iRStoH[iUnit][0] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][0] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][0] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位右上
  p5obj.translate( iCenter + 20, 45 );
  p5obj.drawBox( iRStoH[iUnit][1] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][1] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][1] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位右下
  p5obj.translate( iCenter + 20, 120 );
  p5obj.drawBox( iRStoH[iUnit][2] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][2] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][2] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位下部
  p5obj.translate( iCenter, 180 );
  p5obj.drawBox( iRStoH[iUnit][3] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][3] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][3] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位左下
  p5obj.translate( iCenter - 65, 120 );
  p5obj.drawBox( iRStoH[iUnit][4] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][4] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][4] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位左上
  p5obj.translate( iCenter - 65, 45 );
  p5obj.drawBox( iRStoH[iUnit][5] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][5] );
  p5obj.translate( 0, 20 );
  p5obj.drawBox( iRStoH[iUnit][5] );
  
  p5obj.pop();
  p5obj.push();
  //秒数一の位中央
  p5obj.translate( iCenter, 102.5 );
  p5obj.drawBox( iRStoH[iUnit][6] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][6] );
  p5obj.translate( -22.5, 0 );
  p5obj.drawBox( iRStoH[iUnit][6] );
  
  p5obj.pop();
}

p5obj.drawColon = (iColonPosX: number, iColonPosY: number): void =>
{
  p5obj.push();
  p5obj.noFill();
  p5obj.stroke( 255 );
  p5obj.translate( iColonPosX, iColonPosY );
  //回転し続ける骨組み立方体コロンを書く
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 180 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 180 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 270 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 270 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 180 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 180 ) ) );
  p5obj.endShape( p5obj.CLOSE );
 
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 270 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 270 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR ) ) , iYL * p5obj.sin( p5obj.radians( iColonR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 270 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 270 ) ) );
  p5obj.endShape( p5obj.CLOSE );
  
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR ) ) , iYL * p5obj.sin( p5obj.radians( iColonR ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 90 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 90 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 90 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 90 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR ) ) );
  p5obj.endShape( p5obj.CLOSE );
  
  p5obj.beginShape();
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 90 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 90 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 180 ) ) , iYL * p5obj.sin( p5obj.radians( iColonR + 180 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 180 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 180 ) ) );
  p5obj.vertex( iRL * p5obj.cos( p5obj.radians( iColonR + 90 ) ) + iXL , iYL * p5obj.sin( p5obj.radians( iColonR + 90 ) ) );
  p5obj.endShape( p5obj.CLOSE );
  
  iColonR += 0.5;
  p5obj.pop();
}
};

export default sketch;
