const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR = p.sin(iX/0.75)*p.sin(iY/78.5);
    fG = (p.tan(iX/0.80+0.41)-p.sin(iY/7.22*0.5))/p.tan(iX/0.80+0.41);
    fB = p.sin(iX/1.0)/1.0+5.0;
    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
