p5obj.drawrod = () =>//釣り竿の描写
{  

  if( animeM2 == 1 )  // アニメーション中
  { let rF: number = 0;

    if( rodTimer <= 1 )
    {
      rF = rodTimer;
      p5obj.push();
      p5obj.translate(310,370);
      p5obj.rotate(-p5obj.sin(rF*p5obj.PI)/4);
      //竿
      p5obj.strokeWeight(3);
      p5obj.noFill();
      p5obj.bezier(0,0,-0,-10-p5obj.sin(rF*p5obj.PI)*80,130,-150-p5obj.sin(rF*p5obj.PI)*60,290,-160);
      //糸
      p5obj.strokeWeight(1);
      p5obj.stroke(240);
      p5obj.bezier(290,-160,290+p5obj.sin(rF*p5obj.PI)*150,130-p5obj.sin(rF*p5obj.PI)*30,290-p5obj.sin(rF*p5obj.PI)*200,-270+p5obj.sin(rF*p5obj.PI)*50,290-p5obj.sin(rF*p5obj.PI)*20,140-p5obj.sin(rF*p5obj.PI)*120);
      
      p5obj.pop();
      
      rodTimer += deltaTime;
    }
    else
    {
      p5obj.strokeWeight(3);
      p5obj.noFill();
      p5obj.bezier(310,370,300,360,440,220,600,210);
    
      p5obj.strokeWeight(1);
      p5obj.stroke(240);
      p5obj.bezier(600,210,600,350,600,310,600,510);
      animeM2 = 0;
    }
  }
    // 10秒ごとのアニメーション
  else if ( sI % 10 == 0 )
  {
    let iX: number = 0;
    if (deltaTimePerSec<=0.1)
    {
      p5obj.strokeWeight(3);
      p5obj.noFill();
      p5obj.bezier(310,370,300,360,440,220,600,215);
      
      p5obj.strokeWeight(1);
      p5obj.stroke(240);
      p5obj.bezier(600,215,600,350,600,310,600,510);
    }
    else if (deltaTimePerSec<=0.2)
    {
      iX += 5*(deltaTimePerSec -0.1)*10/9*10;
      
      p5obj.strokeWeight(3);
      p5obj.noFill();
      p5obj.bezier(310,370,300,360,440,220,600,215-iX);
      
      p5obj.strokeWeight(1);
      p5obj.stroke(240);
      p5obj.bezier(600,215-iX,600,350,600,310,600,510);
    }
    else
    {
      p5obj.strokeWeight(3);
      p5obj.noFill();
      p5obj.bezier(310,370,300,360,440,220,600,210);
      
      p5obj.strokeWeight(1);
      p5obj.stroke(240);
      p5obj.bezier(600,210,600,350,600,310,600,510);
    }
  }
  else
  {
    p5obj.strokeWeight(3);
    p5obj.noFill();
    p5obj.bezier(310,370,300,360,440,220,600,210);
  
    p5obj.strokeWeight(1);
    p5obj.stroke(240);
    p5obj.bezier(600,210,600,350,600,310,600,510);
  }
}

p5obj.drawhamon = () =>//波紋を書く
{
  if (mI ==minutePrev)
  {
    if (sI !=secondPrev )
    {
      animeS = 1;
      hamonTimer = 0;
    }
    if (animeS == 1)
    {
      let hF: number = 0;

      if(hamonTimer<0.5)
      {
        hF=hamonTimer;
        p5obj.strokeWeight(1);
        p5obj.stroke(255,255,240,255-hF*400);
        p5obj.ellipse(600,513,hF*100,hF*40);
        hamonTimer +=deltaTime;
      }
    }
  }
    if (animeSs == 1)
  {
    let hF: number = 0;

    if(hamonsTimer<0.6)
    {
      hF=hamonsTimer;
      p5obj.strokeWeight(1);
      p5obj.stroke(255,255,240,255-hF*450);
      p5obj.ellipse(600,513,hF*550,hF*65);
      hamonsTimer +=deltaTime;
    } 
    else
    {
     animeSs =0; 
    }
  }
}

