p5obj.drawfish = () =>//魚
{
  
  if(fishTimer==0)
  {
    ffffffish = p5obj.random(0,10);
    Fc[0]=p5obj.random(60,200);
    Fc[1]=p5obj.random(60,200);
    Fc[2]=p5obj.random(60,200);
  }
  
    if( animeM3 == 1 )  // アニメーション中
  { 
    if( fishTimer <= 2 )
    {
      sF=fishTimer;
      p5obj.stroke(230);
  
      
      if(ffffffish <=6.5) 
      {
        p5obj.fish1();
      }
      else if(ffffffish <=9)
      {
        p5obj.fish2();
      }
      else if(ffffffish <=9.9)
      {
       p5obj.fish3(); 
      }
      else p5obj.dejou();
    
      fishTimer += deltaTime;
    }
    else 
    {
     animeM3 =0; 
    }
  }
}

