// === Time Handling Functions===
p5obj.initTime = () =>
{
  hI = p5obj.hour();
  mI = p5obj.minute();
  sI = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = () =>
{ 
  if( hourPrev != p5obj.hour() ) hI = p5obj.hour();
  if( minutePrev != p5obj.minute() ) mI = p5obj.minute();
  if( secondPrev != p5obj.second() ) sI = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( sI != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = () =>
{ 
  hourPrev = hI;
  minutePrev = mI;
  secondPrev = sI;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = () =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

