const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.HSB, 360, 100, 100 );
p5obj.background( 180, 80, 35 ); //閭梧勹
p5obj.noStroke();

p5obj.push();

//鮟・
p5obj.blendMode( p5obj.MULTIPLY );
//邵ｦ
for ( var iY= 0; iY < 500; iY += 100 )
{
  for ( var iX = 0; iX < 7; iX++ )
  {
    p5obj.fill( 10, 100, 30 ); //豼・
    p5obj.rect( iX, 0, 10, 500 ); //邱・
    p5obj.translate(15, 0); // X霆ｸ譁ｹ蜷代↓15遘ｻ蜍・
  }
  p5obj.translate(75, 0); // X霆ｸ譁ｹ蜷代↓75遘ｻ蜍・
}
p5obj.push();

p5obj.push();

//讓ｪ
for ( var iY= 0; iY < 500; iY += 100 )
{
  for ( var iX = 0; iX < 7; iX ++ )
  {
    p5obj.fill( 10, 100, 30 ); //豼・
    p5obj.rect( 0, iX, 500, 10 ); //邱・

    p5obj.translate(0, 15); // Y霆ｸ譁ｹ蜷代↓15遘ｻ蜍・
  }
  p5obj.translate(0, 75); // Y霆ｸ譁ｹ蜷代↓75遘ｻ蜍・
}

p5obj.push();

//逋ｽ
p5obj.blendMode( p5obj.ADD );
//邵ｦ
p5obj.push();
for ( var iY= 0; iY < 500; iY += 100 )
{
  for ( var iX = 0; iX < 7; iX++ )
  {
    p5obj.fill( 60, 10, 80 ); //逋ｽ
    p5obj.rect( iX+3, 0, 4, 500 ); //邱・

    p5obj.translate(15, 0); // X霆ｸ譁ｹ蜷代↓15遘ｻ蜍・
  }
  p5obj.translate(75, 0); // X霆ｸ譁ｹ蜷代↓75遘ｻ蜍・
}
p5obj.push();


//讓ｪ
p5obj.push();
for ( var iY= 0; iY < 500; iY += 100 )
{
  for ( var iX = 0; iX < 7; iX ++ )
  {
    p5obj.fill( 60, 10, 80 ); //逋ｽ
    p5obj.rect( 0, iX+3, 500, 4 ); //邱・

    p5obj.translate(0, 15); // Y霆ｸ譁ｹ蜷代↓15遘ｻ蜍・
  }
  p5obj.translate(0, 75); // Y霆ｸ譁ｹ蜷代↓75遘ｻ蜍・
}

p5obj.push();

//鮟・牡
p5obj.blendMode( p5obj.BLEND );
//邵ｦ
p5obj.strokeWeight( 3 );
for ( var iX = 0; iX < 500; iX += 180 )
{
  p5obj.stroke( 40, 50, 90 );
  p5obj.line( iX+142, 0, iX+142, 500 );
}

//讓ｪ
p5obj.strokeWeight( 3 );
for ( var iX = 0; iX < 500; iX += 180 )
{
  p5obj.stroke( 40, 50, 90 );
  p5obj.line( 0, iX+142, 500, iX+142 );
}

  };
};

export default sketch;
