// 正方形描画
p5obj.drawsquare = (sqX: number, sqY: number, sqwiX: number, sqhiY: number): void => {
  p5obj.strokeWeight(2);
  p5obj.stroke(100);
  p5obj.fill(252);
  p5obj.rectMode(p5obj.CORNER);
  p5obj.rect(sqX * 40, sqY * 40, sqwiX, sqhiY, 10);
}

// レーン描画
p5obj.drawlane = (laX: number, laY: number, laXY: number): void => {
  p5obj.strokeWeight(2);
  p5obj.stroke(100);
  p5obj.fill(160);
  p5obj.rectMode(p5obj.RADIUS);
  //if横着
let lawiX: number = (laXY == 0) ? 15 : 20;
let lahiY: number = (laXY == 0) ? 20 : 15;
  p5obj.rect(20 + laX * 40, 20 + laY * 40, lawiX, lahiY);
}

// レーン角描画
p5obj.drawklane = (lakX: number, lakY: number, anglek: number): void => {
let baseX: number = lakX * 40;
let baseY: number = lakY * 40;
let angleK: number = (anglek-1) * 90;

  p5obj.push();
  p5obj.translate(baseX, baseY);
  p5obj.rotate(p5obj.radians(angleK));
  if (anglek % 10 == 1) {
    p5obj.translate(-baseX, -baseY);
  } else if (anglek % 10 == 2) {
    p5obj.translate(-baseX+40, -baseY);
  } else if (anglek % 10 == 3) {
    p5obj.translate(-baseX+40, -baseY-40);
  } else if (anglek % 10 == 4) {
    p5obj.translate(-baseX, -baseY-40);
  }

  p5obj.beginShape();
  p5obj.fill(120);
  p5obj.vertex(baseX - 35, baseY);
  for (let theta = p5obj.PI; theta >= p5obj.HALF_PI; theta -= 0.01) {
let rA: number = 5;
    p5obj.vertex(p5obj.cos(theta) * rA + baseX, p5obj.sin(theta) * rA + baseY );
  }
  for (let theta = p5obj.HALF_PI; theta <= p5obj.PI; theta += 0.01) {
let rB: number = 35;
    p5obj.vertex(p5obj.cos(theta) * rB + baseX, p5obj.sin(theta) * rB + baseY);
  }
  p5obj.endShape();
  p5obj.pop();
}

//1/4円
p5obj.qCircle = (qCircleX: number, qCircleY: number, qCircleR: number, qColor: number): void => {
  // 四分の一円を描画
  p5obj.push();
  p5obj.translate(qCircleX, qCircleY);
  if (qCircleR % 10 == 1) {
    p5obj.rotate(p5obj.HALF_PI);
  } else if (qCircleR % 10 == 2) {
    p5obj.rotate(p5obj.PI);
  } else if (qCircleR % 10 == 3) {
    p5obj.rotate(p5obj.PI + p5obj.HALF_PI);
  }
  if (qColor % 10 == 0) {
    p5obj.fill(30, 150, 200);
  } else if (qColor % 10 == 1) {
    p5obj.fill(30, 10, 200);
  } else if (qColor % 10 == 2) {
    p5obj.fill(180, 60, 255);
  }
  p5obj.noStroke();
  p5obj.arc(0, 0, 25, 25, p5obj.HALF_PI, p5obj.PI);
  p5obj.pop();
}

//1/2円
p5obj.hCircle = (hCircleX: number, hCircleY: number, hCircleR: number, hColor: number): void => {
  p5obj.push();
  p5obj.translate(hCircleX, hCircleY);
  if (hCircleR % 10 == 1) {
    p5obj.rotate(p5obj.HALF_PI);
  } else if (hCircleR % 10 == 2) {
    p5obj.rotate(p5obj.PI);
  } else if (hCircleR % 10 == 3) {
    p5obj.rotate(p5obj.PI + p5obj.HALF_PI);
  }
  p5obj.noStroke();
  {
    if (hColor % 10 == 0) {
      p5obj.fill(30, 150, 200);
    } else if (hColor % 10 == 1) {
      p5obj.fill(10, 220, 180);
    } else if (hColor % 10 == 2) {
      p5obj.fill(30, 150, 200);
    } else if (hColor % 10 == 3) {
      p5obj.fill(180, 60, 255);
    } else if (hColor % 10 == 4) {
      p5obj.fill(30, 10, 200);
    } else if (hColor % 10 == 5) {
      p5obj.fill(30, 150, 200);
    }
    p5obj.arc(0, 0, 25, 25, 0, p5obj.PI / 2); // 0度から90度まで
    if (hColor % 10 == 0) {
      p5obj.fill(30, 10, 200);
    } else if (hColor % 10 == 1) {
      p5obj.fill(10, 220, 180);
    } else if (hColor % 10 == 2) {
      p5obj.fill(30, 150, 200);
    } else if (hColor % 10 == 3) {
      p5obj.fill(180, 60, 255);
    } else if (hColor % 10 == 4) {
      p5obj.fill(30, 10, 200);
    } else if (hColor % 10 == 5) {
      p5obj.fill(30, 150, 200);
    }
    p5obj.arc(0, 0, 25, 25, p5obj.PI / 2, p5obj.PI); // 90度から180度まで
  }
  p5obj.pop();
}

