const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);
p.colorMode(p.RGB, 255);//繧ｫ繝ｩ繝ｼ繝｢繝ｼ繝会ｼ・GB縲・00谿ｵ髫趣ｼ・
p.background(60, 128, 90);//閭梧勹 縺ｿ縺ｩ繧・

var X=0;//x霆ｸ縺ｫ郢ｰ繧願ｿ斐☆縺溘ａ縺ｮ螟画焚
var Y=30;//y霆ｸ縺ｫ郢ｰ繧願ｿ斐☆縺溘ａ縺ｮ螟画焚
var r=50;//蝓ｺ貅悶→縺ｪ繧句・蠑ｧ縺ｮ逶ｴ蠕・
var kakudo=0;//隗貞ｺｦ縺ｮ螟画焚
var x=0;//貂ｦ蟾ｻ縺阪・荳ｭ蠢ベ
var y=0;//貂ｦ蟾ｻ縺阪・荳ｭ蠢ペ
var P=0;//y霆ｸ縺ｫ郢ｰ繧願ｿ斐＠縺滓凾縺ｮx霆ｸ縺ｮ繧ｺ繝ｬ

p.stroke(255);//邱壹・逋ｽ
p.strokeWeight(4);
p.noFill();

for (var iy=0; iy<6; iy++)//y霆ｸ縺ｮ郢ｰ繧願ｿ斐＠
{
  for (var ix=0; ix<20; ix++)//x霆ｸ縺ｮ郢ｰ繧願ｿ斐＠
  {
    x=X;
    y=Y;
    for (var  iu=0; iu<4; iu++)//貂ｦ蟾ｻ縺・
    {
      p.arc(x, y, r, r, p.radians( kakudo ), p.radians( kakudo +180 ), p.OPEN);
      x=x+(r/4)*p.cos(p.radians(kakudo));
      y=y+(r/4)*p.sin(p.radians(kakudo));
      kakudo=kakudo+180;
      r=r/2;
    }
    r=40;
    kakudo=kakudo+90;
    x=x+25*p.cos(p.radians(kakudo-45))+(r/2)*p.cos(p.radians(kakudo+20));
    y=y+25*p.sin(p.radians(kakudo-45))+(r/2)*p.sin(p.radians(kakudo));
    for (var  iu=0; iu<4; iu++)//貂ｦ蟾ｻ縺・
    {
      p.arc(x, y, r, r, p.radians( kakudo + 180 ), p.radians( kakudo + 360 ), p.OPEN);
      x=x+(r/4)*p.cos(p.radians(kakudo));
      y=y+(r/4)*p.sin(p.radians(kakudo));
      kakudo=kakudo+180;
      r=r/2;
    }
    r=20;
    kakudo=kakudo-90;
    x=x+20*p.cos(p.radians(kakudo))+(r/2)*p.cos(p.radians(kakudo));
    y=y+20*p.sin(p.radians(kakudo))+(r/2)*p.sin(p.radians(kakudo));
    for (var  iu=0; iu<4; iu++)//貂ｦ蟾ｻ縺・
    {
      p.arc(x, y, r, r, p.radians( kakudo + 180 ), p.radians( kakudo + 360 ), p.OPEN);
      x=x+(r/4)*p.cos(p.radians(kakudo));
      y=y+(r/4)*p.sin(p.radians(kakudo));
      kakudo=kakudo+180;
      r=r/2;
    }
    X=X+49.5;
    r=50;
    kakudo=kakudo+180;
  }
  P=P-40;
  X=P;
  Y=Y+110;
}

  };
};

export default sketch;
