const sketch = (p5obj:any) => {
/**************************************************************
 パソコン画面をイメージした時計。
 背景色は時間帯によって変化。こちらのプログラムは授業内のサンプルプログラムを参考にした。
 Now Loading please wait...〇と書かれたウインドウが一秒おきに増える。
 〇内の数字は現在の秒数。
 このウィンドウはランダムな位置から画面左下に向かって重なって表示され、
 端に来るとまたランダムな位置から左下に向かう描画がされる。
 分が変わると４０４エラーメッセージのウィンドウが表示される。メッセージ最下部の数字は現在の分。
 時が変わるとおめでとうメッセージ。現在の時刻で何人目の訪問者か変わる。
 10％の確率で背景が虹色になる。
 分、時刻が変化した際に表示されるウィンドウの色はランダム。
 
 **************************************************************/
/**
 デバッグ機能
 'S'キー：png出力
 'H'キー：時が変わったときのアニメーション再生
 'M'キー：分が変わったときのアニメーション再生
 */
// === 'S'キーを押した時の出力画像名 ===
//  "K3_[クラス][番号]_[苗字].png"
let pngName: String = "K3_A12_fukushima.png";

// === アニメーション用変数/定数 ===
let winX: number;
let winY: number;
let winHeight: number;
let winWidth: number;
let winm: number;
let batsuXL: number;
let batsuXR: number;
let winXQ: number;
let winYQ: number;
let winHeightQ: number;
let winWidthQ: number;
let winmQ: number;
let batsuXLQ: number;
let batsuXRQ: number;
let mousex: number;
let mousey: number;
let iY: number = 0;
let iWidth: number = 40;
let iRepeat: number = 400;

let iBackGroundRGB: number[][]
  = [
  [239, 219, 0 ], // 朝
  [ 3, 199, 255 ], // 昼
  [ 205, 53, 0 ], // 夕
  [  27, 13, 230 ] ];  // 夜


// === Time Handling ===
let hourCurrent: number;       // 現在の時（0~23）
let minuteCurrent: number;     // 現在の分（0~59）
let secondCurrent: number;     // 現在の秒（0~59）
let deltaTime: number;       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number; // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;

p5obj.setup = (): void =>
{
  p5obj.colorMode(p5obj.RGB);
  p5obj.createCanvas( 600, 600 );
  p5obj.frameRate( 4);  // フレームレートの指定




  // アニメーション初期化
  winX = p5obj.random(500);
  winY = p5obj.random(600);
  winWidth = p5obj.random(100, 120);
  winHeight = p5obj.random(80, 90);
  winm = winHeight / 8;
  batsuXL = winX + winWidth - 8;
  batsuXR = winX + winWidth - 2;

  mousex=p5obj.random(300);
  mousey=p5obj.random(600);

  // === Time Init ===
  p5obj.initTime();
}

p5obj.draw = (): void =>
{
  // === Time Update ===
  p5obj.updateTimePre();

  //hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化

  // 背景色の設定
let iHour: number = p5obj.hour();
let iHourElem: number = 0;
  if ( iHour >= 5 && iHour <= 10 )  // 朝
  {
    iHourElem = 0;
  } else if ( iHour >= 11 && iHour <= 16 )  // 昼
  {
    iHourElem = 1;
  } else if ( iHour >= 17 && iHour <= 19 )  // 夕
  {
    iHourElem = 2;
  } else  // 夜
  {
    iHourElem = 3;
  }
  p5obj.noStroke();
  p5obj.fill( iBackGroundRGB[iHourElem][0], iBackGroundRGB[iHourElem][1], iBackGroundRGB[iHourElem][2], 2);
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );


  // 既定の描画カラーに戻す．
  p5obj.stroke( 0 );
  p5obj.strokeWeight(1);

  //背景の不透明ウィンドウ
  p5obj.blendMode( p5obj.MULTIPLY );
  winXQ = p5obj.random(600);
  winYQ = p5obj.random(600);
  winHeightQ = p5obj.random(40, 60);
  winWidthQ = p5obj.random(80, 90);
  winmQ = winHeightQ / 8;
  batsuXLQ = winXQ + winWidthQ - 8;
  batsuXRQ = winXQ + winWidthQ - 2;

  // //ウィンドウ全体
  p5obj.stroke(0, 50);
  p5obj.fill(p5obj.random(255), p5obj.random(0, 50), p5obj.random(0, 50), 50);
  p5obj.rect(winXQ, winYQ, winWidthQ, winHeightQ);
  // ウィンドウ上部
  p5obj.fill(255, 50);
  p5obj.rect(winXQ, winYQ, winWidthQ, winmQ);
  //ウィンドウ内部
  p5obj.rect(winXQ + 4, winYQ + winmQ + 4, winWidthQ - 8, winHeightQ - winmQ - 8);
  // バツ印の枠
  p5obj.fill(255, 0, 0, 50);
  p5obj.rect(winXQ + winWidthQ - 10, winYQ, 10, winmQ);
  // バツ印
  p5obj.stroke(255, 50);
  p5obj.line(batsuXLQ, winYQ + 2, batsuXRQ, winYQ + 5);
  p5obj.line(batsuXLQ, winYQ + 5, batsuXRQ, winYQ + 2);
  //文字
  p5obj.fill(0, 50);
  p5obj.textSize(10);
  p5obj.text("Error!", winXQ + winWidthQ / 2.6, winYQ + winHeightQ / 1.8);
  p5obj.text("Error!", winXQ + winWidthQ / 2.6, winYQ + winHeightQ / 1.6);
  p5obj.text("Error!", winXQ + winWidthQ / 2.6, winYQ + winHeightQ / 1.4);

  p5obj.blendMode(p5obj.BLEND);

  // === アニメーションを記述 ===

  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始

    //ウィンドウを左下に向かって描画させる
    winX += p5obj.random(-30, -10);
    winY += p5obj.random(5, 6);


    //ウィンドウが画面端に触れた際に位置をリセット
    if (winX<0)
    {

      winX=p5obj.random(460);
    }
    if (winY >510)
    {
      winY=p5obj.random(510);
    }

    // 変数の更新
    winWidth = p5obj.random(130, 160);
    winHeight = p5obj.random(60, 100);
    winm = winHeight / 8;
    batsuXL = winX + winWidth - 8;
    batsuXR = winX + winWidth - 2;
  }

  if ( isSecondAnim == 1 )  // アニメーション中
  {

    // アニメーション中の処理を記述

    p5obj.stroke(0);
    //ウィンドウ全体
    p5obj.fill( 100, 150, 250 );
    p5obj.rect( winX, winY, winWidth, winHeight );
    //ウィンドウ上部
    p5obj.fill(255);
    p5obj.rect(winX, winY, winWidth, winm);
    //ウィンドウ内部
    p5obj.rect(winX+4, winY+winm+4, winWidth-8, winHeight-winm-8);
    //バツ印の枠
    p5obj.fill(255, 0, 0);
    p5obj.rect(winX+winWidth-10, winY, 10, winm);
    //バツ印
    p5obj.stroke(255);
    p5obj.line(batsuXL, winY+2, batsuXR, winY+5);
    p5obj.line(batsuXL, winY+5, batsuXR, winY+2);

    //ウィンドウ内の文字
    p5obj.textSize( 13 );
    p5obj.fill(p5obj.random(255), p5obj.random(255), p5obj.random(255));
    p5obj.text( "Now Loading...", winX+winWidth/10, winY+winHeight/2.5);
    p5obj.textSize( 15);
    p5obj.fill(0);
    p5obj.text( "Please wait...", winX+winWidth/6.4, winY+winHeight/1.4);
    p5obj.textSize( 25);
    p5obj.text( p5obj.second(), winX+winWidth/1.4, winY+winHeight/1.4);

    //マウスポインター
    p5obj.push();
    p5obj.rotate( p5obj.radians( 340 ) );

    //マウスポインターを左下に向かって描画させる
    mousex+= p5obj.random(-9, -5);
    mousey += p5obj.random(2, 1);

    //マウスポインターが画面端に触れた際に位置をリセット
    if (mousex<0)
    {

      mousex=p5obj.random(300);
    }
    if (mousey >600)
    {
      mousey=p5obj.random(600);
    }

    p5obj.strokeWeight(0.8);
    p5obj.stroke(0);
    p5obj.fill(255);
    p5obj.beginShape();
    p5obj.vertex( mousex, mousey );
    p5obj.vertex( mousex-8, mousey+18 );
    p5obj.vertex( mousex-2, mousey+16 );
    p5obj.vertex( mousex-2, mousey+24 );
    p5obj.vertex( mousex+2, mousey+24 );
    p5obj.vertex( mousex+2, mousey+16 );
    p5obj.vertex( mousex+8, mousey+18 );
    p5obj.endShape(p5obj.CLOSE);
    p5obj.pop();


    isSecondAnim = 0;  // アニメーション終了
  }


  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始

    // アニメーション初期化
    winX = p5obj.random(60, 120);
    winY = p5obj.random(80, 160);
    winWidth = p5obj.random(300, 500);
    winHeight = p5obj.random(200, 300);
    winm = winHeight / 14;
    batsuXL = winX + winWidth - 14;
    batsuXR = winX + winWidth - 4;
  }

  if ( isMinuteAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述
    p5obj.stroke(0);
    //ウィンドウ全体
    p5obj.fill( p5obj.random(255), p5obj.random(255), p5obj.random(255));
    p5obj.rect( winX, winY, winWidth, winHeight );
    //ウィンドウ上部
    p5obj.fill(255);
    p5obj.rect(winX, winY, winWidth, winm);
    //ウィンドウ内部
    p5obj.rect(winX+6, winY+winm+8, winWidth-12, winHeight-winm-12);
    //バツ印の枠
    p5obj.fill(255, 0, 0);
    p5obj.rect(winX+winWidth-18, winY, 18, winm);
    //バツ印
    p5obj.stroke(255);
    p5obj.strokeWeight(2);
    p5obj.line(batsuXL, winY+4, batsuXR, winY+13);
    p5obj.line(batsuXL, winY+13, batsuXR, winY+4);

    //ウィンドウ内の文字
    //404
    p5obj.fill(220, 0, 0);
    p5obj.textSize(80);
    p5obj.text("404", winX+winWidth/3, winY+winHeight/2.5);
    //not found
    p5obj.fill(0);
    p5obj.textSize(50);
    p5obj.text("not found", winX+winWidth/4.5, winY+winHeight/1.7);

    p5obj.fill(0);
    p5obj.textSize(10);
    p5obj.text("The requested URL was not found on this server.", winX+winWidth/4.3, winY+winHeight/1.5);
    p5obj.text("processing/k_3_b14_tanaka.com/", winX+winWidth/3.5, winY+winHeight/1.4);

    p5obj.fill(0);
    p5obj.textSize(10);
    p5obj.text(p5obj.minute(), winX+winWidth/2, winY+winHeight/1.3);


    isMinuteAnim = 0;  // アニメーション終了
  }


  // 時が変化した時のアニメーション
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始

    // アニメーション初期化
    winX = 50;
    winY = 100;
    winWidth = 500;
    winHeight = p5obj.random( 300, 400);
    winm = winHeight / 14;
    batsuXL = winX + winWidth - 14;
    batsuXR = winX + winWidth - 4;
  }

  if ( isHourAnim == 1 )
  {
    // アニメーション中の処理を記述
    /*１０％の確率で背景が虹色になります。授業内のサンプルプログラムを参考にしてます。
     本当は一時間のみ色をおかしくしたかったのですが、
     RGBモードに戻しても一度背景が虹色になると以降ずっと色がおかしいままで原因が分からなかったので仕方なくそのままにしてます。
     */
    if ( p5obj.random( 100 ) < 10 )
    {
      p5obj.colorMode(p5obj.HSB, iRepeat, 1, 1 );
      p5obj.noStroke();
      for( let iX = 0; iX < 600; iX += 40 )
      {
        p5obj.fill( iX % iRepeat, 1, 1 );
        p5obj.rect( iX, iY, iWidth, 600 );
      }

      p5obj.colorMode(p5obj.RGB);
      //ウィンドウ表示
      p5obj.stroke(0);
      p5obj.strokeWeight(2);
      //ウィンドウ全体
      p5obj.fill( p5obj.random(255), p5obj.random(255), p5obj.random(255));
      p5obj.rect( winX, winY, winWidth, winHeight );
      //ウィンドウ上部
      p5obj.fill(255);
      p5obj.rect(winX, winY, winWidth, winm);
      //ウィンドウ内部
      p5obj.rect(winX+6, winY+winm+8, winWidth-12, winHeight-winm-12);
      //バツ印の枠
      p5obj.fill(255, 0, 0);
      p5obj.rect(winX+winWidth-18, winY, 18, winm);
      //バツ印
      p5obj.stroke(255);
      p5obj.strokeWeight(2);
      p5obj.line(batsuXL, winY+4, batsuXR, winY+13);
      p5obj.line(batsuXL, winY+13, batsuXR, winY+4);

      //文字。背景が虹色になるとCONGRATULATIONSも文字化けします
      p5obj.textSize(50);
      p5obj.fill( p5obj.random(255), p5obj.random(255), p5obj.random(255));
      p5obj.text( "おめdeとうｇおざiます!!!！！！！", winX+winWidth/23, winY+winHeight/3 );
      p5obj.textSize(40);
      p5obj.text( p5obj.hour(), winX+winWidth/2.2, winY+winHeight/1.6 );
      p5obj.textSize( 30);
      p5obj.fill(0);
      p5obj.text( "You は、 ", winX+winWidth/2.5, winY+winHeight/2.3 );
      p5obj.text( "t?e", winX+winWidth/2.2, winY+winHeight/2 );
      p5obj.text( "th", winX+winWidth/2.15, winY+winHeight/1.4);
      p5obj.text( "訪もｎ?yaです!!!", winX+winWidth/2.45, winY+winHeight/1.3);
    } else
    {
      p5obj.colorMode(p5obj.RGB);
      p5obj.fill( 204 );
      p5obj.noStroke();
      p5obj.rect( 0, 0, p5obj.width, p5obj.height );

      //ウィンドウ表示
      p5obj.stroke(0);
      p5obj.strokeWeight(2);
      //ウィンドウ全体
      p5obj.fill( p5obj.random(255), p5obj.random(255), p5obj.random(255));
      p5obj.rect( winX, winY, winWidth, winHeight );
      //ウィンドウ上部
      p5obj.fill(255);
      p5obj.rect(winX, winY, winWidth, winm);
      //ウィンドウ内部
      p5obj.rect(winX+6, winY+winm+8, winWidth-12, winHeight-winm-12);
      //バツ印の枠
      p5obj.fill(255, 0, 0);
      p5obj.rect(winX+winWidth-18, winY, 18, winm);
      //バツ印
      p5obj.stroke(255);
      p5obj.strokeWeight(2);
      p5obj.line(batsuXL, winY+4, batsuXR, winY+13);
      p5obj.line(batsuXL, winY+13, batsuXR, winY+4);

      //文字
      p5obj.textSize(50);
      p5obj.fill( p5obj.random(255), p5obj.random(255), p5obj.random(255));
      p5obj.text( "CONGRATULATIONS!!!", winX+winWidth/23, winY+winHeight/3 );
      p5obj.textSize(40);
      p5obj.text( p5obj.hour(), winX+winWidth/2.2, winY+winHeight/1.6 );
      p5obj.textSize( 30);
      p5obj.fill(0);
      p5obj.text( "You are ", winX+winWidth/2.5, winY+winHeight/2.3 );
      p5obj.text( "the", winX+winWidth/2.2, winY+winHeight/2 );
      p5obj.text( "th", winX+winWidth/2.15, winY+winHeight/1.4);
      p5obj.text( "visitor!!!", winX+winWidth/2.45, winY+winHeight/1.3);
    }





    isHourAnim = 0;  // アニメーション終了
  }

  // 時間をデバッグ表示（ 提出前に非表示にすること．）
  /*
   p5obj.fill( 0 );
   p5obj.textSize(20);
   p5obj.text( hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 10, 20);
   p5obj.text( "deltaTimePerSec: " + deltaTimePerSec, 10, 40);
   p5obj.text( "deltaTime: " + deltaTime, 10, 60);
   */
  // === Time Update ===
  p5obj.updateTimePost();
}

// === Time Handling ===
let hourPrev: number;
let minutePrev: number;
let secondPrev: number;
let millisCurrent: number;
let millisPrev: number;
let millisPrevSec: number;
// === Time Handling Functions===
p5obj.initTime = (): void =>
{
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
p5obj.updateTimePre = (): void =>
{ 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
p5obj.updateTimePost = (): void =>
{ 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
p5obj.keyPressed = (): void =>
{
  if ( p5obj.key == 's' )
  {
    p5obj.save(pngName);
  }
  else if ( p5obj.key == 'h' )
  {
    hourPrev = -1;
  }
  else if ( p5obj.key == 'm' )
  {
    minutePrev = -1;
  }
}

};

export default sketch;
